/**
 * Message namespaces used only inside the admin console, the patient cabinet and the partner portal.
 *
 * The root layout sends the public site only the other namespaces (every page's HTML carries the client messages,
 * so this keeps public pages ~30 KB smaller per language); the portal layouts add the full set back with their own
 * NextIntlClientProvider. Generated by checking which namespaces are referenced outside portal code — when you use
 * one of these in a public page's client component, remove it from this list.
 */
export const PORTAL_ONLY_NAMESPACES = [
  "activityMsg", "activityType", "adminRes", "adminUi", "adminVal", "ak", "apptKind", "as", "auditObj", "auditType",
  "auditVerb", "caseEvent", "caseHint", "caseP", "caseType", "caseUi", "channel", "consentScope", "contentUi", "crmUi",
  "dashUi", "dashboardUi", "direction", "doc", "leadSource", "notifType", "notifUi", "p360", "partnerUi", "payDirection",
  "payKind", "payStatus", "pf", "priority", "profileUi", "qs", "quoteStatus", "refStatus", "roles", "rs", "stage",
  "taskStatus", "travelUi", "userMenu", "vs", "walkIn", "workflow",
] as const;

export function publicMessages<T extends Record<string, unknown>>(all: T): Partial<T> {
  const skip = new Set<string>(PORTAL_ONLY_NAMESPACES);
  return Object.fromEntries(Object.entries(all).filter(([k]) => !skip.has(k))) as Partial<T>;
}
